// UnmarshalText implements encoding.TextUnmarshaler. Unknown names are
// errors.
func (i *ItemSkillType) UnmarshalText(text []byte) error {
	v, err := itemSkillTypeTable.unmarshal(text)
	if err != nil {
		return err
	}
	*i = ItemSkillType(v)
	return nil
}

// ParseItemSkillType returns the ItemSkillType with the given name.
func ParseItemSkillType(name string) (ItemSkillType, bool) {
	v, ok := itemSkillTypeTable.parse(name)
	return ItemSkillType(v), ok
}
